"""Domain migration helper (temporary): who fetches the subscription through which host, and - when switched on - the headers that tell the apps the new address.

Why in the panel and not in nginx: HAProxy sends every request for the panel paths straight to the panel (backend `hiddifypanel`), nginx never sees them.

Settings: /opt/hiddify-manager/cabinet/migration.json (re-read when the file changes, no restart; a missing or broken file = everything off)
  log          true = write one line per subscription request to LOG (time, first 8 characters of the account uuid, host, User-Agent, status, tail of the path; no IP address)
  old_hosts    hosts of the OLD subscription address, e.g. ["old.example"]
  new_host     the new subscription host (no scheme, no path)
  headers      true = answer requests that come in on an old host (status 200) with
                 moved-permanently-to: https://<new_host><same path>   (Hiddify app: replaces the stored subscription URL)
                 new-domain: <new_host>                               (Happ: changes only the domain)
Nothing here may ever break a request: every error is swallowed."""
from __future__ import annotations

import json
import os
import re
import threading
import time

from flask import request

CONF = os.environ.get("SUBWATCH_CONF", "/opt/hiddify-manager/cabinet/migration.json")
LOG = os.environ.get("SUBWATCH_LOG", "/opt/hiddify-manager/hiddify-panel/var/sub-watch.log")
MAX_LOG_BYTES = 5 * 1024 * 1024
HOST_RE = re.compile(r"^[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?$")
# /<path>/<uuid>[/tail]: the first segment is the client (or admin) path, the uuid is the account
SUB_RE = re.compile(r"^/[^/]+/([0-9a-f]{8})-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(/.*)?$")
SKIP_TAILS = ("/admin", "/api", "/static")

_lock = threading.Lock()
_cache = {"mtime": None, "conf": {}}


def _conf() -> dict:
    try:
        m = os.stat(CONF).st_mtime_ns
    except OSError:
        _cache.update(mtime=None, conf={})
        return {}
    if m != _cache["mtime"]:
        conf = {}
        try:
            with open(CONF, "r", encoding="utf-8") as fh:
                raw = json.load(fh)
            if isinstance(raw, dict):
                conf["log"] = raw.get("log") is True
                conf["headers"] = raw.get("headers") is True
                conf["old_hosts"] = [h for h in (str(x).strip().lower() for x in raw.get("old_hosts") or []) if HOST_RE.match(h)]
                nh = str(raw.get("new_host") or "").strip().lower()
                conf["new_host"] = nh if HOST_RE.match(nh) else ""
        except Exception:  # noqa: BLE001 - a broken file means "off"
            conf = {}
        _cache.update(mtime=m, conf=conf)
    return _cache["conf"]


def _write(line: str) -> None:
    with _lock:
        try:
            if os.path.getsize(LOG) > MAX_LOG_BYTES:
                os.replace(LOG, LOG + ".1")
        except OSError:
            pass
        with open(LOG, "a", encoding="utf-8") as fh:
            fh.write(line + "\n")


def _after_request(resp):
    try:
        conf = _conf()
        if not conf or not (conf.get("log") or conf.get("headers")):
            return resp
        m = SUB_RE.match(request.path)
        if not m:
            return resp
        tail = m.group(2) or "/"
        if tail.startswith(SKIP_TAILS):
            return resp
        host = (request.host or "").split(":")[0].lower()
        if conf.get("log"):
            ua = re.sub(r"[^\x20-\x7e]", "?", request.headers.get("User-Agent", ""))[:120].replace('"', "'")
            _write(f'{time.strftime("%Y-%m-%dT%H:%M:%S%z")} {m.group(1)} {host} "{ua}" {resp.status_code} "{tail[:40]}"')
        if conf.get("headers") and conf.get("new_host") and host in conf.get("old_hosts", []) and resp.status_code == 200:
            resp.headers["moved-permanently-to"] = f"https://{conf['new_host']}{request.path}"
            resp.headers["new-domain"] = conf["new_host"]
    except Exception:  # noqa: BLE001 - never break a request
        pass
    return resp


def init_app(app) -> None:
    app.after_request(_after_request)
